\begin{itemize}
   \item $2\le N\le 200$
   \item $1\le S\le N$
   \item $0\le K<\frac{N\times (N-1)}2$
   \item Đảm bảo luôn tồn tại phương án để những người dân có thể rời khỏi vương quốc
\end{itemize}
